<template id="row-template"><tr><td><select class="form-select" data-name="product_id" required><option value="">Select product</option>@foreach($products as $p)<option value="{{ $p->id }}">{{ $p->item_code }} — {{ $p->name }}</option>@endforeach</select></td><td><input class="form-control" data-name="quantity" type="number" step="0.0001" min="0.0001" required></td><td><input class="form-control" data-name="unit_cost" type="number" step="0.0001" min="0" required></td><td><button type="button" class="btn btn-light remove"><i class="bi bi-trash"></i></button></td></tr></template>
@push('scripts')<script>let row=0;function add(){const x=document.querySelector('#row-template').content.cloneNode(true);x.querySelectorAll('[data-name]').forEach(e=>e.name=`items[${row}][${e.dataset.name}]`);x.querySelector('.remove').onclick=e=>e.target.closest('tr').remove();document.querySelector('#items tbody').append(x);row++}document.querySelector('#add-row').onclick=add;add();</script>@endpush @endsection
